const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-scanner", node: "Code: Try Lock Folder" } });
const redis = require('redis');
const crypto = require('crypto');
const folder = $input.first().json; // { id, path, suggested_type }

let redisPw = ''; try { redisPw = $env.REDIS_PASSWORD || ''; } catch(e) {}
const client = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });

const LOCK_TTL_MS = 180000; // 3 min - renewed once per file by the Path-Worker (PROJ-72)
const ownerToken = crypto.randomUUID();
const lockKey = `alice:dms:scanner:lock:folder:${folder.id}`;
const lockValue = JSON.stringify({ owner: ownerToken, path: folder.path, folder_id: folder.id, started_at: new Date().toISOString() });

let acquired = false;
try {
  await client.connect();
  const res = await client.set(lockKey, lockValue, { NX: true, PX: LOCK_TTL_MS });
  acquired = (res === 'OK');
  await client.incr(acquired ? 'alice:dms:scanner:dispatch:stats:dispatched' : 'alice:dms:scanner:dispatch:stats:skipped_locked').catch(() => {});
} catch(e) {
  logger.info(`[Dispatcher] Lock attempt error for folder ${folder.id}: ${e.message}`);
  acquired = false;
} finally {
  await client.quit().catch(() => {});
}

return [{ json: { ...folder, _lock_acquired: acquired, lock_owner: acquired ? ownerToken : null } }];

const redis = require('redis');
const folders = $('PG: Active Folders').all();
let redisPw = ''; try { redisPw = $env.REDIS_PASSWORD || ''; } catch(e) {}
const client = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });

let dispatched = 0, skippedLocked = 0, startMs = 0;
try {
  await client.connect();
  const [d, s, startStr] = await Promise.all([
    client.get('alice:dms:scanner:dispatch:stats:dispatched'),
    client.get('alice:dms:scanner:dispatch:stats:skipped_locked'),
    client.get('alice:dms:scanner:dispatch:run_start')
  ]);
  dispatched = parseInt(d || '0', 10);
  skippedLocked = parseInt(s || '0', 10);
  startMs = parseInt(startStr || '0', 10);
  await client.quit();
} catch(e) {
  try { await client.quit(); } catch(qe) {}
}

return [{ json: {
  event: 'alice-dms-scanner-dispatch-complete',
  active_folders: folders.length,
  paths_dispatched: dispatched,
  paths_skipped_locked: skippedLocked,
  runtime_seconds: startMs > 0 ? Math.round((Date.now() - startMs) / 1000) : 0,
  completed_at: new Date().toISOString()
} }];

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-scanner", node: "Code: Init Dispatcher Run" } });
const redis = require('redis');
let redisPw = ''; try { redisPw = $env.REDIS_PASSWORD || ''; } catch(e) {}
const client = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });
try {
  await client.connect();
  await client.del(['alice:dms:scanner:dispatch:stats:dispatched', 'alice:dms:scanner:dispatch:stats:skipped_locked']);
  await client.set('alice:dms:scanner:dispatch:run_start', String(Date.now()));
  await client.quit();
} catch(e) {
  try { await client.quit(); } catch(qe) {}
  logger.info('Redis unavailable for dispatch stats init, continuing: ' + e.message);
}
return $input.all();

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-scanner", node: "Code: Find Stale Paths" } });
const redis = require('redis');
const fs = require('fs');
const statsItem = $input.first().json;

// PROJ-113: the scanner only REPORTS dead paths; alice-dms-lifecycle adapts
// Weaviate first and removes the Redis entries afterwards. If a message gets
// lost, the entry stays and is reported again on the next run.
// Guards against mass deletion:
//  - grace: a missing path is reported only after every active folder completed
//    a full pass that started after the path went missing (a moved file is found
//    at its new location by the path worker first -> update_path, no delete)
//  - share reachable: the share root (/mnt/nas/<share>) must be readable and not empty
//  - ratio: at most DMS_DELETE_MAX_RATIO (default 20 %) of a share's known paths per run
let maxRatio = 0.2;
try { const v = parseFloat($env.DMS_DELETE_MAX_RATIO); if (!isNaN(v) && v > 0 && v <= 1) maxRatio = v; } catch(e) {}
const MISSING_KEY = 'alice:dms:scanner:missing_since';

function exists(p) { try { fs.accessSync(p, fs.constants.F_OK); return true; } catch(e) { return false; } }
function shareRoot(p) { return p.split('/').slice(0, 4).join('/'); }
const shareReachable = {};
function isShareReachable(root) {
  if (shareReachable[root] === undefined) {
    try { shareReachable[root] = fs.readdirSync(root).length > 0; } catch(e) { shareReachable[root] = false; }
  }
  return shareReachable[root];
}

let redisPw = ''; try { redisPw = $env.REDIS_PASSWORD || ''; } catch(e) {}
const client = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });

const outputItems = [];
let deletedFiles = 0, removedPaths = 0, waitingPaths = 0;
const blockedShares = [];
const unreachableShares = new Set();

try {
  await client.connect();
  const pathToHash = await client.hGetAll('alice:dms:path_to_hash') || {};
  const missingSince = await client.hGetAll(MISSING_KEY) || {};

  // oldest completed full pass over all active folders
  const folders = $('PG: Active Folders').all().map(f => f.json);
  let minFullPass = Infinity;
  for (const f of folders) {
    const v = parseInt(await client.get(`alice:dms:scanner:last_full_pass:folder:${f.id}`) || '0', 10);
    minFullPass = Math.min(minFullPass, v);
  }
  if (folders.length === 0) minFullPass = 0;

  const now = Date.now();
  const candidates = {}; // share root -> [{ filePath, fileHash }]
  const knownPerShare = {};
  for (const [filePath, fileHash] of Object.entries(pathToHash)) {
    const root = shareRoot(filePath);
    knownPerShare[root] = (knownPerShare[root] || 0) + 1;
    if (exists(filePath)) {
      if (missingSince[filePath]) await client.hDel(MISSING_KEY, filePath);
      continue;
    }
    if (!isShareReachable(root)) { unreachableShares.add(root); continue; } // not mounted: nothing reported, markers untouched
    const since = parseInt(missingSince[filePath] || '0', 10);
    if (!since) {
      await client.hSet(MISSING_KEY, filePath, String(now));
      waitingPaths++;
      continue;
    }
    if (since >= minFullPass) { waitingPaths++; continue; }
    (candidates[root] = candidates[root] || []).push({ filePath, fileHash });
  }
  // forget missing markers of paths that left the Redis truth
  for (const p of Object.keys(missingSince)) {
    if (pathToHash[p] === undefined) await client.hDel(MISSING_KEY, p);
  }

  for (const [root, list] of Object.entries(candidates)) {
    const known = knownPerShare[root] || 0;
    if (known > 0 && list.length / known > maxRatio) {
      blockedShares.push({ share: root, missing: list.length, known });
      logger.warn(`[alice-dms-scanner] delete limit: ${list.length} of ${known} known paths under ${root} missing (> ${Math.round(maxRatio * 100)} %) — no lifecycle messages for this share; check the share or run alice-dms-reconcile with ignore_delete_limit`);
      continue;
    }
    for (const { filePath, fileHash } of list) {
      const members = await client.sMembers('alice:dms:hash_to_paths:' + fileHash);
      const alive = members.filter(p => p !== filePath && exists(p));
      const detectedAt = new Date().toISOString();
      if (alive.length === 0) {
        deletedFiles++;
        outputItems.push({ json: { _stale_for_deletion: true, action: 'delete_file', file_hash: fileHash, file_path: filePath, detected_at: detectedAt } });
        logger.info('[alice-dms-scanner] delete_file: ' + filePath + ' (hash: ' + fileHash + ')');
      } else {
        removedPaths++;
        outputItems.push({ json: { _stale_for_deletion: true, action: 'remove_path', file_hash: fileHash, file_path: filePath, alive_paths: alive, detected_at: detectedAt } });
        logger.info('[alice-dms-scanner] remove_path: ' + filePath + ', alive at ' + alive.length + ' other path(s)');
      }
    }
  }
  for (const root of unreachableShares) {
    logger.warn(`[alice-dms-scanner] share ${root} not reachable (unreadable or empty) — no lifecycle messages for it this run`);
  }
  if (waitingPaths > 0) {
    logger.info(`[alice-dms-scanner] ${waitingPaths} missing path(s) waiting for a full pass of all folders before being reported`);
  }
  await client.quit();
} catch(e) {
  try { await client.quit(); } catch(qe) {}
  logger.info('[alice-dms-scanner] stale path check error: ' + e.message);
}

outputItems.push({ json: { _stale_for_deletion: false, ...statsItem, deleted_files: deletedFiles, removed_paths: removedPaths, waiting_paths: waitingPaths, delete_limit_blocked: blockedShares, unreachable_shares: [...unreachableShares] } });
return outputItems;
